// Implement the loop. The contract, in full:
//
//   model.chat(messages, options.toolDefs)
//       -> { content: string, toolCalls: [{ id, name, args, parseOk, rawArgs? }] }
//   tools[name](args)
//       -> a JSON-able result, or THROWS an Error if the arguments are wrong
//   return { finalText, messages }
//
// Three checks read what you return. They are described in lesson 2.

async function runAgent(model, tools, userMessage, options) {
  const maxIterations = options.maxIterations;
  const messages = [{ role: 'user', content: userMessage }];

  // TODO 1: loop at most `maxIterations` times. Nothing in the model guarantees it will
  //         ever stop asking for tools, so this loop has to.
  for (let iteration = 1; iteration <= maxIterations; iteration += 1) {
    const reply = await model.chat(messages, options.toolDefs);
    console.log('iteration', iteration, JSON.stringify(reply));

    // TODO 2: if the reply asks for no tools, it IS the answer. Return it.
    //         Careful: a reply can contain text AND ask for a tool in the same turn.

    // TODO 3: push the assistant's reply onto `messages`, tool calls included.

    // TODO 4: for each call in reply.toolCalls:
    //           - if call.parseOk is false, the model's arguments were not JSON
    //           - tools[call.name] may not exist
    //           - the tool may throw
    //         Whatever happens, append ONE message per call with role 'tool' carrying
    //         the result (or the error) as its content. Errors are observations.
  }

  // TODO 5: you ran out of iterations. Say so honestly rather than inventing an answer.
  return { finalText: '', messages };
}
